tinymce.Resource.add('tinymce.html-i18n.help-keynav.th_TH',
'<h1>Getting started with keyboard navigation</h1>\n' +
'\n' +
'<dl>\n' +
'  <dt>Focus the menu bar</dt>\n' +
'  <dd>Windows or Linux: Alt+F9</dd>\n' +
'  <dd>macOS: &#x2325;F9</dd>\n' +
'  <dt>Focus the toolbar</dt>\n' +
'  <dd>Windows or Linux: Alt+F10</dd>\n' +
'  <dd>macOS: &#x2325;F10</dd>\n' +
'  <dt>Focus the footer</dt>\n' +
'  <dd>Windows or Linux: Alt+F11</dd>\n' +
'  <dd>macOS: &#x2325;F11</dd>\n' +
'  <dt>Focus notifications</dt>\n' +
'  <dd>Windows or Linux: Alt+F12</dd>\n' +
'  <dd>macOS: &#x2325;F12</dd>\n' +
'  <dt>Focus the contextual toolbar</dt>\n' +
'  <dd>Windows, Linux or macOS: Ctrl+F9</dd>\n' +
'</dl>\n' +
'\n' +
'<p>Navigation begins on the first UI item, which is highlighted or underlined when applicable.</p>\n' +
'\n' +
'<h1>Navigating between UI sections</h1>\n' +
'\n' +
'<p>Press <strong>Tab</strong> to move to the next UI section.</p>\n' +
'\n' +
'<p>Press <strong>Shift+Tab</strong> to move to the previous UI section.</p>\n' +
'\n' +
'<p>The <strong>Tab</strong> order is:</p>\n' +
'\n' +
'<ol>\n' +
'  <li>The menu bar</li>\n' +
'  <li>Each toolbar group</li>\n' +
'  <li>The sidebar</li>\n' +
'  <li>The element path in the footer</li>\n' +
'  <li>The word count toggle in the footer</li>\n' +
'  <li>The brand link in the footer</li>\n' +
'  <li>The editor resize handle</li>\n' +
'</ol>\n' +
'\n' +
'<p>If a UI section is not visible it is skipped.</p>\n' +
'\n' +
'<p>If the footer has focus and no sidebar is visible, pressing <strong>Shift+Tab</strong> returns focus to the first toolbar group.</p>\n' +
'\n' +
'<h1>Navigating within a UI section</h1>\n' +
'\n' +
'<p>Use the arrow keys to move between items in the focused section.</p>\n' +
'\n' +
'<p><strong>Left</strong> and <strong>Right</strong> arrows</p>\n' +
'\n' +
'<ul>\n' +
'  <li>Move between menus in the menu bar</li>\n' +
'  <li>Open sub-menus</li>\n' +
'  <li>Move between buttons in a toolbar group</li>\n' +
'  <li>Move between items in the element path</li>\n' +
'</ul>\n' +
'\n' +
'<p><strong>Down</strong> and <strong>Up</strong> arrows</p>\n' +
'\n' +
'<ul>\n' +
'  <li>Move between menu items</li>\n' +
'  <li>Move between items in a toolbar pop-up menu</li>\n' +
'</ul>\n' +
'\n' +
'<p>The arrow keys cycle within the focused UI section.</p>\n' +
'\n' +
'<p>Press <strong>Esc</strong> to close any open menus or pop-ups.</p>\n' +
'\n' +
'<p>If focus is at the top of a UI section, pressing <strong>Esc</strong> exits keyboard navigation entirely.</p>\n' +
'\n' +
'<h1>Activating menu items or toolbar buttons</h1>\n' +
'\n' +
'<p>When the desired item is highlighted, press <strong>Return</strong>, <strong>Enter</strong>, or the <strong>Space bar</strong>.</p>\n' +
'\n' +
'<h1>Navigating modal dialog boxes</h1>\n' +
'\n' +
'<p>Non-tabbed dialogs focus the first interactive element when opened.</p>\n' +
'<p>Use <strong>Tab</strong> or <strong>Shift+Tab</strong> to move between controls.</p>\n' +
'\n' +
'<h1>Navigating tabbed dialog boxes</h1>\n' +
'\n' +
'<p>Tabbed dialogs focus the first tab button when opened.</p>\n' +
'<p>Use <strong>Tab</strong> or <strong>Shift+Tab</strong> to move between interactive controls within the dialog.</p>\n' +
'<p>When the tab list has focus, use the arrow keys to switch between available tabs.</p>\n');
